using System;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 public sealed class ChallengeSaveTests
 {
  static string Hash(string text){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","").ToLowerInvariant();}
  static GameState Main(){var s=Game.New(1000000);s.Tutorial="done";s.Credits=s.Data=ScientificNumber.From(10000000);s.Prestige.resets=1;s.Industry.discovered[1]=true;s=Game.Buy(s,"calculator",25);s=Game.Buy(s,"sbc");s=Workshop.Discover(s);s=Workshop.Craft(s,"impulse-relay");s=Workshop.Equip(s,s.Workshop.inventory[0].id);s=Game.Train(s,"quality");s=Game.Research(s,"dataGeneration");s.Workshop.components=Enumerable.Repeat(100000L,ItemBalance.ComponentIds.Length).ToArray();s=Industry.QueueForge(s,s.Workshop.inventory[0].id);s=Industry.Synthesize(s,0);return s;}
  [Test]public void VersionFiveMigratesWithOriginalAndPreservesAllIndustryContracts()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-challenge-v5-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Main();var codec=new UnitySaveCodec();var d=StateData.From(s);d.challengeProgress=null;d.hasChallenge=false;string payload=codec.Encode(d),original=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=5,payload=payload,sha256=Hash(payload)}),path=Path.Combine(dir,"save.json");File.WriteAllText(path,original);var store=new AtomicSaveStore(path,codec);var load=store.Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(JsonUtility.ToJson(StateData.From(load.State)),Is.EqualTo(JsonUtility.ToJson(StateData.From(s))));Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v5-original-*").Single()),Is.EqualTo(original));store.Save(load.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(AtomicSaveStore.Version));Assert.That(File.ReadAllText(path+".backup"),Is.EqualTo(original));}finally{Directory.Delete(dir,true);}}
  [Test]public void MainJobsAndBoostClockPauseAcrossOfflineReloadAndAbortWithoutResourceLeak()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-challenge-durable-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var main=Main();main.ActiveUntil=main.SavedAt+10000;main.CooldownUntil=main.SavedAt+60000;var codec=new UnitySaveCodec();string path=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(path,codec);store.Load(main.SavedAt);store.Save(main);var run=ChallengeRules.Start(main,"no-taps",1,"durable-run");Assert.That(run.Challenges.Run,Is.Not.Null);Assert.That(run.Challenges.Main,Is.Not.SameAs(main));run=Game.Advance(run,main.SavedAt+2*86400000);Assert.That(run.Challenges.Main.Credits.CompareTo(main.Credits),Is.Zero);Assert.That(run.Challenges.Main.Data.CompareTo(main.Data),Is.Zero);Assert.That(run.Challenges.Main.Training.done,Is.EqualTo(main.Training.done));Assert.That(run.Challenges.Main.ResearchJob.done,Is.EqualTo(main.ResearchJob.done));Assert.That(run.Challenges.Main.Industry.synthesis.done,Is.EqualTo(main.Industry.synthesis.done));Assert.That(run.Challenges.Main.Industry.foundries[0].active.done,Is.EqualTo(main.Industry.foundries[0].active.done));Assert.That(run.Challenges.Main.ActiveUntil-run.Challenges.Main.SavedAt,Is.EqualTo(10000));store.Save(run);var loaded=new AtomicSaveStore(path,codec).Load(run.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);ChallengeParityTests.Session(loaded.State,run,"disk roundtrip");Assert.That(Game.Advance(loaded.State,run.SavedAt),Is.SameAs(loaded.State));var aborted=ChallengeRules.Return(loaded.State,false,"durable-run");Assert.That(aborted.Credits.CompareTo(main.Credits),Is.Zero);Assert.That(aborted.SavedAt,Is.EqualTo(run.SavedAt));Assert.That(aborted.Challenges.Main,Is.Null);Assert.That(aborted.Workshop.inventory[0].challengeCopy,Is.False);Assert.That(aborted.Workshop.inventory[0].id,Is.EqualTo(main.Workshop.inventory[0].id));Assert.That(ChallengeRules.Return(aborted,false,"durable-run"),Is.SameAs(aborted));}finally{Directory.Delete(dir,true);}}
  [Test]public void CompletionIsDurableOnceAndTamperedCopiesOrMissingMainCannotLoad()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-challenge-claim-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var main=Main();var run=ChallengeRules.Start(main,"no-taps",1,"claim-run");run.Challenges.Run.metrics.credits=ChallengeRules.Current(run).Goals.First(g=>g.Id=="passive-credits").Target.ToData();Assert.That(ChallengeRules.Ready(run),Is.True);var codec=new UnitySaveCodec();string path=Path.Combine(dir,"save.json");var store=new AtomicSaveStore(path,codec);store.Load(run.SavedAt);store.Save(run);var resumeStore=new AtomicSaveStore(path,codec);var active=resumeStore.Load(run.SavedAt);Assert.That(active.Writable,Is.True,active.Message);var done=ChallengeRules.Return(active.State,true,"claim-run");resumeStore.Save(done);Assert.That(done.Challenges.Progress.stages[0],Is.EqualTo(1));Assert.That(done.Challenges.Progress.stars,Is.EqualTo(2));var restored=new AtomicSaveStore(path,codec).Load(done.SavedAt).State;Assert.That(ChallengeRules.Return(restored,true,"claim-run"),Is.SameAs(restored));Assert.That(restored.Challenges.Progress.completions[0],Is.EqualTo(1));var invalid=run.Copy();invalid.Workshop.inventory.First(i=>i.challengeCopy).level++;Assert.Throws<FormatException>(()=>Game.Validate(invalid));var dto=StateData.From(run);dto.challengeMain=null;Assert.Throws<FormatException>(()=>dto.ToState());dto=StateData.From(run);dto.challengeRun=null;Assert.Throws<FormatException>(()=>dto.ToState());dto=StateData.From(main);dto.challengeProgress=null;Assert.Throws<FormatException>(()=>dto.ToState());}finally{Directory.Delete(dir,true);}}
 }
}
